// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 h1, bytes32 h2, uint256 rollDelta) public {
        vm.assume(actor != address(0));
        vm.assume(rollDelta <= 10);

        vm.deal(actor, 2 ether);
        vm.roll(block.number + rollDelta);

        // first guess is always admissible
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h1);

        // advance one block so the first guess's target block is set
        vm.roll(block.number + 1);

        // RULE: a second lockInGuess by the same actor must revert,
        // because guesses[actor].block != 0 (it was never settled).
        bool ok;
        vm.prank(actor);
        try c.lockInGuess{value: 1 ether}(h2) { ok = true; } catch { ok = false; }

        assertTrue(!ok, "second lockInGuess must revert");
    }
}
